drop function public.approve_application(uuid,uuid,uuid);
create function public.approve_application(p_id uuid,p_cv uuid,p_cover uuid,p_questions_version uuid) returns text language plpgsql security definer set search_path='' as $$ declare uid uuid:=auth.uid(); a public.applications%rowtype; latest_cv uuid; latest_cover uuid; begin if uid is null then return 'not_found'; end if; select * into a from public.applications where id=p_id and user_id=uid for update; if not found then return 'not_found'; end if; if a.status not in ('saved','preparing','review_required','action_required') or exists(select 1 from public.manual_submissions where application_id=p_id) then return 'invalid_state'; end if; if p_questions_version is distinct from a.questions_version then return 'questions_changed'; end if; if exists(select 1 from public.application_questions where application_id=p_id and user_id=uid and not confirmed) then return 'unreviewed_questions'; end if; select id into latest_cv from public.application_documents where application_id=p_id and user_id=uid and kind='cv' order by created_at desc,id desc limit 1; select id into latest_cover from public.application_documents where application_id=p_id and user_id=uid and kind='cover_letter' order by created_at desc,id desc limit 1; if p_cv is distinct from latest_cv or p_cover is distinct from latest_cover then return 'invalid_document'; end if; insert into public.application_approvals(application_id,user_id,cv_document_id,cover_document_id,questions_version) values(p_id,uid,p_cv,p_cover,a.questions_version); update public.applications set status='action_required',updated_at=now() where id=p_id; insert into public.application_events(application_id,user_id,event) values(p_id,uid,'Preparation approved for manual handoff'); return 'approved'; end $$;
revoke all on function public.approve_application(uuid,uuid,uuid,uuid) from public; grant execute on function public.approve_application(uuid,uuid,uuid,uuid) to authenticated;
